<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('admin',['hr_manager']);csrf_check();$a=$_POST['_action']??'';
if($a==='mark'&&in_array($_POST['status'],ATT)){set_att((int)$_POST['emp'],$_POST['date'],$_POST['status'],$u['id'],trim($_POST['reason'])?:'Manual entry');audit($u['id'],'Attendance edit emp #'.(int)$_POST['emp'].' '.$_POST['date']);flash('Saved');redirect('attendance.php');}
if($a==='import'&&is_uploaded_file($_FILES['f']['tmp_name']??'')&&$_FILES['f']['size']<2000000){$h=fopen($_FILES['f']['tmp_name'],'r');$ok=0;$bad=[];$ln=0;fgetcsv($h);
 while(($r=fgetcsv($h))!==false){$ln++;[$c,$dt,$st]=array_pad(array_map('trim',$r),3,'');$q=db()->prepare("SELECT id FROM employees WHERE employee_code=?");$q->execute([$c]);$id=$q->fetchColumn();$d=DateTime::createFromFormat('Y-m-d',$dt);
  if(!$id||!$d||$d->format('Y-m-d')!==$dt||!in_array($st,ATT)){$bad[]="Row $ln";continue;}set_att($id,$dt,$st,$u['id'],'CSV import');$ok++;}
 fclose($h);audit($u['id'],"Attendance CSV import: $ok rows");flash("Imported $ok rows".($bad?'; skipped: '.implode(', ',array_slice($bad,0,15)):''),$bad?'warning':'success');redirect('attendance.php');}
$emps=db()->query("SELECT id,employee_code,full_name FROM employees ORDER BY employee_code")->fetchAll();
$log=db()->query("SELECT l.*,e.employee_code FROM attendance_audit_logs l LEFT JOIN employees e ON e.id=l.employee_id ORDER BY l.id DESC LIMIT 25")->fetchAll();page_head('Attendance',[],$u);?>
<form method="post" class="card p-3 mb-3 row g-2 flex-row"><?=csrf_field()?><input type="hidden" name="_action" value="mark"><div class="col-md-3"><select class="form-select" name="emp"><?php foreach($emps as $x)echo'<option value="'.$x['id'].'">'.e($x['employee_code'].' – '.$x['full_name']).'</option>';?></select></div><div class="col-md-2"><input class="form-control" type="date" name="date" required></div><div class="col-md-2"><select class="form-select" name="status"><?php foreach(ATT as $s)echo"<option>$s</option>";?></select></div><div class="col-md-3"><input class="form-control" name="reason" placeholder="Reason"></div><div class="col-md-2"><button class="btn btn-primary w-100">Mark</button></div></form>
<form method="post" enctype="multipart/form-data" class="card p-3 mb-4 d-flex flex-row gap-2 align-items-center"><?=csrf_field()?><input type="hidden" name="_action" value="import"><input class="form-control w-auto" type="file" name="f" accept=".csv" required><button class="btn btn-outline-primary">Import CSV</button><span class="small text-muted">Header row, then: employee_code,date(YYYY-MM-DD),status</span></form>
<div class="card table-responsive"><table class="table mb-0"><tr><th>When</th><th>Emp</th><th>Date</th><th>Change</th><th>Reason</th></tr><?php foreach($log as $l)echo'<tr><td>'.e($l['created_at']).'</td><td>'.e($l['employee_code']).'</td><td>'.e($l['att_date']).'</td><td>'.e(($l['old_status']?:'—').' → '.$l['new_status']).'</td><td>'.e($l['reason']).'</td></tr>';?></table></div><?php page_foot();
